<?php
$header=is_array($document['header']??null)?$document['header']:[];
$summary=is_array($document['variance_summary']??null)?$document['variance_summary']:[];
$rows=is_array($document['variance_items']??null)?$document['variance_items']:[];
$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
?><!doctype html><html><head><meta charset="utf-8"><title>SVP</title><style>@page{size:80mm auto;margin:0}*{box-sizing:border-box}body{width:79mm;margin:0;font:10px Arial;color:#000}.svp{padding:2mm}.center{text-align:center}.stars{white-space:nowrap;overflow:hidden;font-weight:bold}h1{font-size:17px;margin:2px 0}h2{font-size:12px;margin:5px 0 2px;border-bottom:1px solid #000;padding-bottom:2px}.meta{display:flex;justify-content:space-between}table{width:100%;border-collapse:collapse}td,th{padding:2px 1px;border-bottom:1px dotted #777;text-align:left}td:not(:first-child),th:not(:first-child){text-align:right}.short{color:#9c1f1f;font-weight:bold}.surplus{color:#0d6b2f;font-weight:bold}.empty{text-align:center;padding:5px}</style></head><body><main class="svp"><header class="center"><div class="stars">***********************************************************</div><h1><?= $esc($header['counter_name']??'') ?> SVP</h1><div><?= $esc($header['company_name']??'') ?></div><div>SHIFT: <?= $esc($header['shift']??$header['shift_date']??'') ?></div><div>COUNTED BY: <?= $esc($header['counted_by']??$header['user']??$header['served_by']??'') ?></div><div><?= $esc($header['print_time']??'') ?></div><div class="stars">***********************************************************</div></header><section><h2>VARIANCE SUMMARY</h2><table><?php foreach($summary as $key=>$value): if(is_array($value))continue; ?><tr><td><?= $esc(ucwords(str_replace('_',' ',$key))) ?></td><td><?= $esc($value) ?></td></tr><?php endforeach; ?></table></section><section><h2>VARIANCE ITEMS</h2><?php if(!$rows): ?><div class="empty">All counted items are balanced.</div><?php else: ?><table><thead><tr><th>Item</th><th>Expected</th><th>Counted</th><th>Variance</th></tr></thead><tbody><?php foreach($rows as $row): $row=is_array($row)?$row:[];$v=(float)($row['variance']??0);$class=$v<0?'short':($v>0?'surplus':''); ?><tr><td><?= $esc($row['item']??$row['name']??$row['item_name']??'') ?></td><td><?= $esc($row['expected']??$row['system_qty']??0) ?></td><td><?= $esc($row['counted']??$row['counted_qty']??0) ?></td><td class="<?= $class ?>"><?= $v>0?'+':'' ?><?= $esc(rtrim(rtrim(number_format($v,2,'.',''),'0'),'.')) ?></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></section><footer class="center"><div class="stars">***********************************************************</div>END OF STOCK VARIANCE</footer></main></body></html>
